(
      (select id from public.content_pages where page_key = 'home'),
      'en', 'published', 'Nobel ITBS | Professional Education and Verifiable Documents', 'Professional Nobel ITBS programmes in business, technology and psychology. Distance learning for adults and documents that can be verified online.',
      'Education that moves you forward', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Professional education for adults","h1":"Education that moves you forward","lead":"Professional programmes for development, career change and new opportunities in business, technology and working with people.","supporting_text":"Nobel ITBS combines applied learning, an international context and a clear document system with online verification.","primary_cta":"Explore programmes","primary_cta_target":"`/programmes`"},"body":"","cards":[]},{"key":"verification_utility","title":"Verification Utility","fields":{"title":"Verify a document","body":"Enter the document number or scan the QR code to check its status.","input_label":"Document number","input_placeholder":"For example, NITBS-C-2026-000123","submit_label":"Verify","link_label":"How verification works","link_target":"`/verify`"},"body":"issue date, or successful verification result.","cards":[]},{"key":"programme_areas","title":"Programme Areas","fields":{"eyebrow":"Programme areas","h2":"Choose your professional pathway","intro":"Each area brings together programmes with a clear professional goal, defined learning format and transparent outcome."},"body":"","cards":[{"title":"Business & Management","fields":{"title":"Business & Management","body":"Management, entrepreneurship, AI production and competencies for developing businesses and teams.","featured_programme":"AI Production"},"body":""},{"title":"Technology & Innovation","fields":{"title":"Technology & Innovation","body":"Technology markets, innovation and emerging industries at the intersection of technology, economics and management.","featured_programme":"Space Business"},"body":""}]},{"key":"featured_programmes","title":"Featured Programmes","fields":{"eyebrow":"Nobel ITBS programmes","h2":"Learning with a clear purpose","intro":"Five programmes in different formats, from continuously available distance courses to a Mini-MBA and partner professional development programmes.","section_cta":"Explore all programmes"},"body":"Programme cards are populated from the programme catalogue and must use approved programme master copy. The Home page must not maintain a second independent version of programme duration, price, document, or instruction-language facts.","cards":[]},{"key":"why_nobel_itbs","title":"Why Nobel ITBS","fields":{"eyebrow":"Why Nobel ITBS","h2":"Education you can trust","lead":"We build learning as a complete professional pathway, from a clear programme and outcomes to a properly issued document."},"body":"","cards":[{"title":"Applied Professional Education","fields":{"title":"Applied professional education","body":"Programmes focus on competencies that can be used in professional work and further development."},"body":""},{"title":"Structured Learning","fields":{"title":"Clear structure","body":"The format, duration, content, learning outcomes and document are described before learning begins."},"body":""},{"title":"Own And Partner Programmes","fields":{"title":"Own and partner programmes","body":"Nobel ITBS creates its own educational products and provides infrastructure for partner programmes."},"body":""}]},{"key":"how_the_model_works","title":"How The Model Works","fields":{"eyebrow":"From programme to confirmed outcome","h2":"Learning, document, verification","step_1_title":"Choose a programme","step_1_body":"Compare its purpose, content, format, duration and learning outcome.","step_2_title":"Complete your learning","step_2_body":"Learn in the format defined by the programme and meet its completion requirements.","step_3_title":"Receive your document","step_3_body":"The type and scope of the document depend on the specific programme and are published on its page.","step_4_title":"Confirm its authenticity","step_4_body":"If the document is registered with Nobel ITBS, its status can be verified online."},"body":"","cards":[]},{"key":"for_organisations","title":"For Organisations","fields":{"eyebrow":"For online schools and experts","h2":"Infrastructure for educational programmes and documents","body":"Nobel ITBS helps online schools, experts and authors structure educational programmes and develop a document model. The infrastructure may include preparing documents and supplements, registration and online verification.","primary_cta":"For organisations","secondary_link":"Partnerships"},"body":"","cards":[]},{"key":"institutional_bridge","title":"Institutional Bridge","fields":{"eyebrow":"About Nobel ITBS","h2":"A European platform for professional education","body":"Nobel ITBS is a European professional education platform for adults and organisations, working across Business & Management, Technology & Innovation and Psychology & Human.","cta":"Learn more about Nobel ITBS","cta_target":"`/about`"},"body":"","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"h2":"Find a programme for your next step","body":"Explore the programme areas, compare formats and choose the programme that matches your professional goal.","cta":"Explore programmes"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'home'),
      'ua', 'published', 'Nobel ITBS | Професійна освіта та верифіковані документи', 'Професійні програми Nobel ITBS у бізнесі, технологіях та психології. Дистанційне навчання для дорослих і документи, які можна перевірити онлайн.',
      'Освіта, що рухає вперед', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Професійна освіта для дорослих","h1":"Освіта, що рухає вперед","lead":"Професійні програми для розвитку, зміни кар''єри та нових рішень у бізнесі, технологіях і роботі з людьми.","supporting_text":"Nobel ITBS поєднує прикладне навчання, міжнародний контекст і зрозумілу систему документів із можливістю онлайн-верифікації.","primary_cta":"Переглянути програми","primary_cta_target":"`/ua/programmes`"},"body":"","cards":[]},{"key":"verification_utility","title":"Verification Utility","fields":{"title":"Перевірити документ","body":"Введіть номер документа або відскануйте QR-код, щоб перевірити його статус.","input_label":"Номер документа","input_placeholder":"Наприклад, NITBS-C-2026-000123","submit_label":"Перевірити","link_label":"Як працює верифікація","link_target":"`/ua/verify`"},"body":"issue date, or successful verification result.","cards":[]},{"key":"programme_areas","title":"Programme Areas","fields":{"eyebrow":"Напрями навчання","h2":"Оберіть професійну траєкторію","intro":"Кожен напрям об''єднує програми з чіткою професійною метою, визначеним форматом навчання та зрозумілим результатом."},"body":"","cards":[{"title":"Business & Management","fields":{"title":"Business & Management","body":"Управління, підприємництво, AI-продюсування та компетентності для розвитку бізнесу й команд.","featured_programme":"AI Production"},"body":""},{"title":"Technology & Innovation","fields":{"title":"Technology & Innovation","body":"Технологічні ринки, інновації та нові індустрії на перетині технологій, економіки й управління.","featured_programme":"Space Business"},"body":""}]},{"key":"featured_programmes","title":"Featured Programmes","fields":{"eyebrow":"Програми Nobel ITBS","h2":"Навчання з конкретною метою","intro":"П''ять програм різного формату — від постійно доступних дистанційних курсів до Mini-MBA та партнерських програм професійного розвитку.","section_cta":"Переглянути всі програми"},"body":"Programme cards are populated from the programme catalogue and must use approved programme master copy. The Home page must not maintain a second independent version of programme duration, price, document, or instruction-language facts.","cards":[]},{"key":"why_nobel_itbs","title":"Why Nobel ITBS","fields":{"eyebrow":"Чому Nobel ITBS","h2":"Освіта, якій можна довіряти","lead":"Ми будуємо навчання як цілісну професійну траєкторію: від зрозумілої програми та результатів до належно оформленого документа."},"body":"","cards":[{"title":"Applied Professional Education","fields":{"title":"Прикладна професійна освіта","body":"Програми орієнтовані на компетентності, які можна використовувати у професійній діяльності та подальшому розвитку."},"body":""},{"title":"Structured Learning","fields":{"title":"Зрозуміла структура","body":"Формат, тривалість, зміст, результати навчання та документ описуються до початку навчання."},"body":""},{"title":"Own And Partner Programmes","fields":{"title":"Власні та партнерські програми","body":"Nobel ITBS створює власні освітні продукти та надає інфраструктуру для партнерських програм."},"body":""}]},{"key":"how_the_model_works","title":"How The Model Works","fields":{"eyebrow":"Від програми до підтвердженого результату","h2":"Навчання, документ, верифікація","step_1_title":"Обираєте програму","step_1_body":"Порівнюєте мету, зміст, формат, тривалість і результат навчання.","step_2_title":"Проходите навчання","step_2_body":"Навчаєтеся у визначеному програмою форматі та виконуєте умови її завершення.","step_3_title":"Отримуєте документ","step_3_body":"Вид документа та його обсяг залежать від конкретної програми й публікуються на її сторінці.","step_4_title":"Підтверджуєте справжність","step_4_body":"Якщо документ зареєстрований у Nobel ITBS, його статус можна перевірити онлайн."},"body":"","cards":[]},{"key":"for_organisations","title":"For Organisations","fields":{"eyebrow":"Для онлайн-шкіл та експертів","h2":"Інфраструктура для освітніх програм і документів","body":"Nobel ITBS допомагає онлайн-школам, експертам і авторам структурувати освітні програми та вибудовувати модель документів. Інфраструктура може включати підготовку документів і додатків, реєстрацію та онлайн-верифікацію.","primary_cta":"Для організацій","secondary_link":"Партнерства"},"body":"","cards":[]},{"key":"institutional_bridge","title":"Institutional Bridge","fields":{"eyebrow":"Про Nobel ITBS","h2":"Європейська платформа професійної освіти","body":"Nobel ITBS — європейська платформа професійної освіти для дорослих та організацій, що працює на перетині Business & Management, Technology & Innovation і Psychology & Human.","cta":"Дізнатися більше про Nobel ITBS","cta_target":"`/ua/about`"},"body":"","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"h2":"Знайдіть програму для свого наступного кроку","body":"Перегляньте напрями, порівняйте формати й оберіть програму, що відповідає вашій професійній меті.","cta":"Переглянути програми"},"body":"","cards":[]}]}'::jsonb
