      'Vzdělávání, které vás posouvá', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Profesní vzdělávání pro dospělé","h1":"Vzdělávání, které vás posouvá","lead":"Profesní programy pro rozvoj, změnu kariéry a nové možnosti v byznysu, technologiích a práci s lidmi.","supporting_text":"Nobel ITBS propojuje prakticky zaměřené vzdělávání, mezinárodní kontext a srozumitelný systém dokumentů s online ověřováním.","primary_cta":"Prohlédnout programy","primary_cta_target":"`/cz/programmes`"},"body":"","cards":[]},{"key":"verification_utility","title":"Verification Utility","fields":{"title":"Ověřit dokument"},"body":"`body`:","cards":[]},{"key":"programme_areas","title":"Programme Areas","fields":{"eyebrow":"Oblasti vzdělávání"},"body":"`h2`:","cards":[]},{"key":"featured_programmes","title":"Featured Programmes","fields":{"eyebrow":"Programy Nobel ITBS","h2":"Vzdělávání s konkrétním cílem","intro":"Pět programů v různých formátech, od trvale dostupných distančních kurzů až po Mini-MBA a partnerské programy profesního rozvoje.","section_cta":"Prohlédnout všechny programy"},"body":"Programové karty čerpají údaje ze schválených master-copy a nesmějí udržovat samostatnou verzi délky, ceny, dokumentu ani jazyka výuky.","cards":[]},{"key":"why_nobel_itbs","title":"Why Nobel ITBS","fields":{"eyebrow":"Proč Nobel ITBS","h2":"Vzdělávání, kterému můžete důvěřovat","lead":"Vzdělávání vytváříme jako ucelenou profesní cestu, od jasného programu a výsledků až po řádně vydaný dokument.","title_1":"Prakticky zaměřené profesní vzdělávání","body_1":"Programy se zaměřují na kompetence využitelné v profesní činnosti a dalším rozvoji.","title_2":"Srozumitelná struktura","body_2":"Formát, délka, obsah, výsledky a dokument jsou popsány před zahájením.","title_3":"Vlastní a partnerské programy","body_3":"Nobel ITBS vytváří vlastní vzdělávací produkty a poskytuje infrastrukturu partnerským programům.","title_4":"Ověřitelné dokumenty","body_4":"Stav dokumentů registrovaných u Nobel ITBS lze ověřit podle čísla nebo QR kódu."},"body":"","cards":[]},{"key":"how_the_model_works","title":"How The Model Works","fields":{"eyebrow":"Od programu k potvrzenému výsledku","h2":"Vzdělávání, dokument, ověření","step_1_title":"Vyberete si program","step_1_body":"Porovnáte cíl, obsah, formát, délku a výsledek vzdělávání.","step_2_title":"Absolvujete vzdělávání","step_2_body":"Studujete ve stanoveném formátu a splníte podmínky dokončení."},"body":"`step_3_title`:","cards":[]},{"key":"for_organisations","title":"For Organisations","fields":{"eyebrow":"Pro online školy a experty","h2":"Infrastruktura pro vzdělávací programy a dokumenty","body":"Nobel ITBS pomáhá online školám, expertům a autorům strukturovat vzdělávací programy a vytvářet model dokumentů. Infrastruktura může zahrnovat přípravu dokumentů a dodatků, registraci a online ověřování.","primary_cta":"Pro organizace","secondary_link":"Partnerství"},"body":"","cards":[]},{"key":"institutional_bridge","title":"Institutional Bridge","fields":{"eyebrow":"O Nobel ITBS","h2":"Evropská platforma profesního vzdělávání","body":"Nobel ITBS je evropská platforma profesního vzdělávání pro dospělé a organizace působící v oblastech Business & Management, Technology & Innovation a Psychology & Human.","cta":"Více o Nobel ITBS","cta_target":"`/cz/about`"},"body":"","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"h2":"Najděte program pro svůj další krok","body":"Prohlédněte si oblasti, porovnejte formáty a vyberte program odpovídající vašemu profesnímu cíli.","cta":"Prohlédnout programy"},"body":"","cards":[]}]}'::jsonb
