(
      (select id from public.content_pages where page_key = 'about'),
      'en', 'published', 'About Nobel ITBS | Professional Education in Europe', 'Discover Nobel ITBS, a European professional education platform for adults and organisations offering its own and partner programmes, documents and online verification.',
      'Professional education for a changing world', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"About Nobel ITBS","h1":"Professional education for a changing world","lead":"Nobel ITBS is a European professional education platform for adults and organisations. We create professional programmes and help partners transform educational expertise into a structured product with properly issued documents."},"body":"","cards":[]},{"key":"who_we_are","title":"Who We Are","fields":{"eyebrow":"Who we are","h2":"A European platform for professional education","body":"Nobel ITBS works at the intersection of professional education, partnership and technology infrastructure. We bring together programmes in three areas: Business & Management, Technology & Innovation and Psychology & Human."},"body":"We do not position Nobel ITBS as a university. Our role is to create and organise professional learning, collaborate with academic and industry partners, and provide a clear system for documents and their verification.","cards":[]},{"key":"why_we_exist","title":"Why We Exist","fields":{"eyebrow":"Our purpose","h2":"Making professional development clear and verifiable","body":"Before learning begins, adult learners need to understand what they will learn, how they will learn, how long it will take and what outcome they will receive. Organisations and education experts need infrastructure that helps turn content into a coherent programme and properly document its outcomes."},"body":"Nobel ITBS brings these needs together in one system, from programme presentation to a document that can be verified.","cards":[]},{"key":"two_areas_of_work","title":"Two Areas Of Work","fields":{"eyebrow":"How Nobel ITBS works","h2":"Two connected areas of work"},"body":"","cards":[{"title":"Professional Programmes","fields":{"title":"Professional programmes","body":"We create and co-develop programmes for adults who want to deepen their competencies, change their professional pathway or prepare for a new role. Each programme has a defined purpose, audience, content, format, learning outcomes and document."},"body":""}]},{"key":"our_educational_approach","title":"Our Educational Approach","fields":{"eyebrow":"Our approach","h2":"Not an isolated course, but a professional pathway","intro":"We assess a programme not by the amount of information it contains, but by how clearly it guides the learner towards a defined outcome."},"body":"","cards":[{"title":"Relevance","fields":{"title":"Professional relevance","body":"Content should reflect real professional tasks and the context of its specific audience."},"body":""},{"title":"Structure","fields":{"title":"Clear structure","body":"The purpose, modules, format, duration, assessment and completion requirements should be defined in advance."},"body":""},{"title":"Transparency","fields":{"title":"Transparency","body":"We distinguish between programme type, learning delivery and the document issued upon completion."},"body":""}]},{"key":"european_and_czech_foundation","title":"European And Czech Foundation","fields":{"eyebrow":"Our foundation","h2":"A Czech company working in an international context","body":"Nobel ITBS s.r.o. operates as a Czech legal entity in the European professional education environment. This shapes our approach to transparency, responsibility, partnerships and document management."},"body":"identification number, and registry reference only after the legal data are provided and verified.","cards":[]},{"key":"exclusive_academic_partnership","title":"Exclusive Academic Partnership","fields":{"eyebrow":"Exclusive academic partnership","h2":"Our connection with the University of Alfred Nobel","body":"The University of Alfred Nobel is the exclusive academic partner of Nobel ITBS. The partnership connects a European professional education platform with the University''s academic expertise and long-standing experience."},"body":"For specific programmes, the University provides the academic foundation and issues professional development documents in accordance with the approved programme terms. The document type and the role of each party are always stated on the relevant programme page.","cards":[]},{"key":"principles","title":"Principles","fields":{"eyebrow":"Our principles","h2":"How we make educational decisions","principle_1_title":"Practical value","principle_1_body":"Learning should help people act with greater confidence in their professional context.","principle_2_title":"Lifelong learning","principle_2_body":"Professional development does not end with a single diploma or programme.","principle_3_title":"Openness to partnership","principle_3_body":"Strong educational products emerge at the intersection of academic, industry and entrepreneurial expertise.","principle_4_title":"Responsible wording","principle_4_body":"We clearly explain the programme status, each party''s role and the document type without overstating academic claims."},"body":"","cards":[]},{"key":"who_we_work_with","title":"Who We Work With","fields":{"eyebrow":"Who we work with","learner_title":"Adult learners","learner_body":"People who want to develop their competencies, move into a new professional role or systematise their existing experience.","organisation_title":"Organisations","organisation_body":"Online schools and educational projects that need infrastructure for programmes, documents, registration and verification.","partner_title":"Authors and education partners","partner_body":"Experts and authors who want to structure a programme and confirm learning outcomes with properly issued documents."},"body":"","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"h2":"Choose how you want to work with Nobel ITBS","body":"Explore professional programmes or discover how we work with organisations and education partners.","primary_cta":"Explore programmes","primary_cta_target":"`/programmes`","secondary_cta":"For organisations","secondary_cta_target":"`/for-organisations`"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'about'),
      'ua', 'published', 'Про Nobel ITBS | Професійна освіта в Європі', 'Дізнайтеся про Nobel ITBS — європейську платформу професійної освіти для дорослих і організацій, власні та партнерські програми, документи й онлайн-верифікацію.',
      'Професійна освіта для світу, що змінюється', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Про Nobel ITBS","h1":"Професійна освіта для світу, що змінюється","lead":"Nobel ITBS — європейська платформа професійної освіти для дорослих та організацій. Ми створюємо професійні програми й допомагаємо партнерам перетворювати освітню експертизу на структурований продукт із належно оформленими документами."},"body":"","cards":[]},{"key":"who_we_are","title":"Who We Are","fields":{"eyebrow":"Хто ми","h2":"Європейська платформа професійної освіти","body":"Nobel ITBS працює на перетині професійної освіти, партнерства та технологічної інфраструктури. Ми об''єднуємо програми у трьох напрямах: Business & Management, Technology & Innovation і Psychology & Human."},"body":"Ми не позиціонуємо Nobel ITBS як університет. Наша роль — створювати й організовувати професійне навчання, співпрацювати з академічними та галузевими партнерами, а також забезпечувати зрозумілу систему документів і їх верифікації.","cards":[]},{"key":"why_we_exist","title":"Why We Exist","fields":{"eyebrow":"Наша мета","h2":"Зробити професійний розвиток зрозумілим і підтверджуваним","body":"Дорослим слухачам важливо ще до початку навчання розуміти, чого вони навчаться, у якому форматі, скільки це триватиме і який результат вони отримають. Організаціям та освітнім експертам потрібна інфраструктура, яка допомагає перетворити зміст на послідовну програму й належно оформити її результати."},"body":"Nobel ITBS поєднує ці потреби в одній системі — від презентації програми до документа, який можна перевірити.","cards":[]},{"key":"two_areas_of_work","title":"Two Areas Of Work","fields":{"eyebrow":"Як працює Nobel ITBS","h2":"Два взаємопов''язані напрями"},"body":"","cards":[{"title":"Professional Programmes","fields":{"title":"Професійні програми","body":"Ми створюємо та спільно розробляємо програми для дорослих, які хочуть поглибити компетентності, змінити професійну траєкторію або підготуватися до нової ролі. Кожна програма має визначені мету, аудиторію, зміст, формат, результати навчання та документ."},"body":""}]},{"key":"our_educational_approach","title":"Our Educational Approach","fields":{"eyebrow":"Наш підхід","h2":"Не окремий курс, а професійна траєкторія","intro":"Ми оцінюємо програму не за кількістю інформації, а за тим, наскільки зрозуміло вона веде слухача до визначеного результату."},"body":"","cards":[{"title":"Relevance","fields":{"title":"Професійна релевантність","body":"Зміст має відповідати реальним професійним завданням і контексту конкретної аудиторії."},"body":""},{"title":"Structure","fields":{"title":"Чітка структура","body":"Мета, модулі, формат, тривалість, оцінювання та умови завершення мають бути визначені заздалегідь."},"body":""},{"title":"Transparency","fields":{"title":"Прозорість","body":"Ми розділяємо тип програми, організацію навчання та документ, який видається після завершення."},"body":""}]},{"key":"european_and_czech_foundation","title":"European And Czech Foundation","fields":{"eyebrow":"Наша основа","h2":"Компанія в Чехії, робота в міжнародному контексті","body":"Nobel ITBS s.r.o. працює як чеська юридична особа у європейському середовищі професійної освіти. Це визначає наш підхід до прозорості, відповідальності, партнерств і роботи з документами."},"body":"identification number, and registry reference only after the legal data are provided and verified.","cards":[]},{"key":"exclusive_academic_partnership","title":"Exclusive Academic Partnership","fields":{"eyebrow":"Ексклюзивне академічне партнерство","h2":"Зв''язок з Університетом імені Альфреда Нобеля","body":"Університет імені Альфреда Нобеля є ексклюзивним академічним партнером Nobel ITBS. Партнерство поєднує європейську платформу професійної освіти з академічною експертизою та багаторічним досвідом Університету."},"body":"У межах окремих програм Університет забезпечує академічну основу та видає документи про підвищення кваліфікації відповідно до затверджених умов програми. Тип документа й роль кожної сторони завжди зазначаються на сторінці конкретної програми.","cards":[]},{"key":"principles","title":"Principles","fields":{"eyebrow":"Наші принципи","h2":"Як ми приймаємо освітні рішення","principle_1_title":"Практична цінність","principle_1_body":"Навчання має допомагати людині діяти впевненіше у професійному контексті.","principle_2_title":"Навчання впродовж життя","principle_2_body":"Професійний розвиток не завершується одним дипломом або однією програмою.","principle_3_title":"Відкритість до партнерства","principle_3_body":"Сильні освітні продукти виникають на перетині академічної, галузевої та підприємницької експертизи.","principle_4_title":"Відповідальність у формулюваннях","principle_4_body":"Ми чітко пояснюємо статус програми, роль кожної сторони та вид документа без перебільшених академічних обіцянок."},"body":"","cards":[]},{"key":"who_we_work_with","title":"Who We Work With","fields":{"eyebrow":"Для кого ми працюємо","learner_title":"Для дорослих слухачів","learner_body":"Для тих, хто хоче розвинути компетентності, перейти до нової професійної ролі або систематизувати наявний досвід.","organisation_title":"Для організацій","organisation_body":"Для онлайн-шкіл та освітніх проєктів, яким потрібна інфраструктура програми, документів, реєстрації та верифікації.","partner_title":"Для авторів і освітніх партнерів","partner_body":"Для експертів і авторів, які хочуть структурувати програму та підтвердити результати навчання належно оформленими документами."},"body":"","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"h2":"Оберіть свій формат співпраці з Nobel ITBS","body":"Перегляньте професійні програми або дізнайтеся, як ми працюємо з організаціями та освітніми партнерами.","primary_cta":"Переглянути програми","primary_cta_target":"`/ua/programmes`","secondary_cta":"Для організацій","secondary_cta_target":"`/ua/for-organisations`"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'about'),
      'cz', 'published', 'O Nobel ITBS | Profesní vzdělávání v Evropě', 'Poznejte Nobel ITBS, evropskou platformu profesního vzdělávání pro dospělé a organizace, její vlastní a partnerské programy, dokumenty a online ověřování.',
      'Profesní vzdělávání pro měnící se svět', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"O Nobel ITBS","h1":"Profesní vzdělávání pro měnící se svět","lead":"Nobel ITBS je evropská platforma profesního vzdělávání pro dospělé a organizace. Vytváříme profesní programy a pomáháme partnerům proměňovat vzdělávací expertizu ve strukturovaný produkt s řádně vydanými dokumenty."},"body":"","cards":[]},{"key":"who_we_are","title":"Who We Are","fields":{"eyebrow":"Kdo jsme","h2":"Evropská platforma profesního vzdělávání","body":"Nobel ITBS působí na průsečíku profesního vzdělávání, partnerství a technologické infrastruktury. Sdružujeme programy v oblastech Business & Management, Technology & Innovation a Psychology & Human."},"body":"Nobel ITBS není prezentována jako univerzita. Naší rolí je vytvářet a organizovat profesní vzdělávání, spolupracovat s akademickými a oborovými partnery a zajišťovat srozumitelný systém dokumentů a jejich ověřování.","cards":[]},{"key":"why_we_exist","title":"Why We Exist","fields":{"eyebrow":"Náš účel"},"body":"`h2`:","cards":[]},{"key":"two_areas_of_work","title":"Two Areas Of Work","fields":{"eyebrow":"Jak Nobel ITBS funguje","h2":"Dvě propojené oblasti činnosti","title_1":"Profesní programy","body_1":"Vytváříme a společně vyvíjíme programy pro dospělé, kteří chtějí prohloubit kompetence, změnit profesní cestu nebo se připravit na novou roli. Každý program má vymezený cíl, publikum, obsah, formát, výsledky a dokument.","title_2":"Infrastruktura partnerských programů","body_2":"Pomáháme expertům a organizacím strukturovat vzdělávací produkt a potvrzovat výsledky. Podle modelu může zahrnovat dokumenty a dodatky, registraci a veřejné ověření stavu dokumentu."},"body":"","cards":[]},{"key":"our_educational_approach","title":"Our Educational Approach","fields":{"eyebrow":"Náš přístup","h2":"Ne izolovaný kurz, ale profesní cesta","intro":"Program neposuzujeme podle množství informací, ale podle toho, jak jasně vede účastníka k vymezenému výsledku.","title_1":"Profesní relevance","body_1":"Obsah má odpovídat reálným profesním úkolům a kontextu publika.","title_2":"Jasná struktura","body_2":"Cíl, moduly, formát, délka, hodnocení a podmínky dokončení jsou určeny předem.","title_3":"Transparentnost","body_3":"Rozlišujeme typ programu, organizaci výuky a dokument vydaný po dokončení.","title_4":"Ověřitelnost","body_4":"Stav dokumentů registrovaných u Nobel ITBS lze ověřit číslem nebo QR kódem bez veřejného přístupu k soukromému PDF."},"body":"","cards":[]},{"key":"european_and_czech_foundation","title":"European And Czech Foundation","fields":{"eyebrow":"Náš základ","h2":"Česká společnost v mezinárodním kontextu","body":"Nobel ITBS s.r.o. působí jako česká právnická osoba v evropském prostředí profesního vzdělávání. To formuje náš přístup k transparentnosti, odpovědnosti, partnerstvím a práci s dokumenty."},"body":"","cards":[]},{"key":"exclusive_academic_partnership","title":"Exclusive Academic Partnership","fields":{"eyebrow":"Exkluzivní akademické partnerství","h2":"Propojení s Univerzitou Alfreda Nobela","body":"Univerzita Alfreda Nobela je exkluzivním akademickým partnerem Nobel ITBS. Partnerství propojuje evropskou platformu profesního vzdělávání s akademickou expertizou a dlouholetými zkušenostmi Univerzity.","proof_1_title":"Více než 30 let zkušeností ve vzdělávání","proof_1_body":"Univerzita Alfreda Nobela rozvíjí vzdělávání na Ukrajině více než 30 let.","proof_2_title":"EIT Deep Tech Talent Initiative","proof_2_body":"Univerzita se stala první ukrajinskou univerzitou zapojenou do EIT Deep Tech Talent Initiative.","proof_3_title":"Space Business","proof_3_body":"Program Space Business Univerzity byl přijat v rámci EIT Deep Tech Talent Initiative."},"body":"U konkrétních programů Univerzita poskytuje akademický základ a vydává dokumenty profesního rozvoje podle schválených podmínek. Typ dokumentu a role stran jsou vždy uvedeny na stránce programu.","cards":[]},{"key":"principles","title":"Principles","fields":{"eyebrow":"Naše principy","h2":"Jak přijímáme vzdělávací rozhodnutí","principle_1_title":"Praktická hodnota","principle_1_body":"Vzdělávání má člověku pomáhat jednat jistěji v profesním kontextu.","principle_2_title":"Celoživotní vzdělávání","principle_2_body":"Profesní rozvoj nekončí jedním diplomem ani jedním programem.","principle_3_title":"Otevřenost partnerství","principle_3_body":"Silné vzdělávací produkty vznikají na průsečíku akademické, oborové a podnikatelské expertizy.","principle_4_title":"Odpovědnost ve formulacích","principle_4_body":"Jasně vysvětlujeme status programu, roli každé strany a typ dokumentu bez přehnaných akademických slibů."},"body":"","cards":[]},{"key":"who_we_work_with","title":"Who We Work With","fields":{"learner_title":"Dospělí účastníci","learner_body":"Lidé rozvíjející kompetence, přecházející do nové profesní role nebo systematizující zkušenosti.","organisation_title":"Organizace","organisation_body":"Online školy a vzdělávací projekty potřebující infrastrukturu programů, dokumentů, registrace a ověřování.","partner_title":"Autoři a vzdělávací partneři","partner_body":"Experti a autoři, kteří chtějí strukturovat program a potvrdit výsledky řádně vydanými dokumenty."},"body":"","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{},"body":"`h2`:","cards":[]}]}'::jsonb
    ),
