      (select id from public.content_pages where page_key = 'partnerships'),
      'en', 'published', 'Nobel ITBS Partnerships | Education and Expertise', 'Nobel ITBS partnership models for educational organisations, online schools, experts and authors of professional programmes.',
      'Partnerships that strengthen professional education', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Partnerships","h1":"Partnerships that strengthen professional education","lead":"We collaborate with organisations and experts who create meaningful programmes and take responsibility for learning outcomes.","supporting_copy":"A partnership may include programme development or presentation, expert participation, education infrastructure, documents, registration and verification. Roles and responsibilities are defined separately for each project.","primary_cta":"Propose a partnership"},"body":"","cards":[]},{"key":"partnership_principles","title":"Partnership Principles","fields":{},"body":"- clear roles and responsibilities for all parties; - transparent authorship and appropriate expert presentation; - verified content and accurate public claims; - defined learning outcomes and completion requirements; - a separate document model for each programme; - respect for intellectual property, learner data and professional boundaries.","cards":[]},{"key":"partnership_models","title":"Partnership Models","fields":{},"body":"","cards":[{"title":"Programme Partnership","fields":{},"body":"For organisations, online schools and methodology owners who want to jointly structure, present or deliver a professional programme."},{"title":"Expert Partnership","fields":{},"body":"For practitioners, lecturers and authors who contribute to content development, teaching, assessment or professional expertise."},{"title":"Infrastructure Partnership","fields":{},"body":"For educational projects that need a document and supplement model, registration and online verification of learning outcomes."}]},{"key":"academic_foundation","title":"Academic Foundation","fields":{"heading":"Exclusive academic partnership","body":"Alfred Nobel University is the exclusive academic partner of Nobel ITBS. The University''s participation and the type of university document are determined separately for each programme and do not automatically extend to all partner projects."},"body":"","cards":[]},{"key":"partner_organisations","title":"Partner Organisations","fields":{"heading":"Partner organisations","intro":"These are organisations whose role in specific programmes or projects has been approved for publication."},"body":"","cards":[{"title":"Riga Nordic University","fields":{"location":"Riga, Latvia","partner_role":"Partner organisation","official_url":"https://rnu.lv/en/","asset_status":"The official site provided a horizontal white SVG and a blue circular PNG mark.","publication_status":"The current partner card and received logo variants are approved for Release 1."},"body":""},{"title":"Nataliia Kholodenko Psychology Centre","fields":{"partner_role":"Partner organisation","official_url":"https://school.kholodenko.net/","asset_status":"The official square PNG mark has been obtained from the Centre''s landing page.","publication_status":"The current partner card and received mark are approved for Release 1."},"body":""},{"title":"e-launch Online School","fields":{"partner_role":"Partner organisation","official_url":"https://e-launch.net/","asset_status":"A square PNG containing the horizontal `e-launch` logo has been received.","publication_status":"The current partner card and received logo are approved for Release 1."},"body":""}]},{"key":"experts","title":"Experts","fields":{"heading":"Experts and programme authors","intro":"Meet the professionals who create content, teach or provide professional expertise within specific programmes."},"body":"","cards":[{"title":"Nataliia Kholodenko","fields":{"public_category":"Psychologist, Candidate of Sciences","expert_role":"Expert and educational programme author","asset_status":"A portrait photograph has been received in JPEG format.","publication_status":"The current concise profile and photograph are approved for Release 1."},"body":""},{"title":"Dmytro Shevchuk","fields":{"public_category":"Practitioner in marketing and educational project production","asset_status":"A portrait photograph has been received in PNG format.","publication_status":"The current concise profile, photograph and AI Production expert role are approved for Release 1."},"body":""}]},{"key":"partnership_boundaries","title":"Partnership Boundaries","fields":{},"body":"- partner and expert pages are not created in Release 1; - a logo is not proof of accreditation or universal endorsement; - partner participation is stated only for the relevant programme or project; - partners never appear in public credential verification data; - cooperation does not automatically create an academic partnership or a right to issue university documents.","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"heading":"Have a programme, expertise or partnership idea?","copy":"Tell us about your role, project and expected cooperation model. We will consider how it may fit the direction of Nobel ITBS.","primary_cta":"Propose a partnership","fallback_cta":"Contact us"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'partnerships'),
      'ua', 'published', 'Партнерства Nobel ITBS | Освіта та експертиза', 'Моделі партнерства Nobel ITBS для освітніх організацій, онлайн-шкіл, експертів і авторів професійних програм.',
      'Партнерства, що підсилюють професійну освіту', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Partnerships","h1":"Партнерства, що підсилюють професійну освіту","lead":"Ми співпрацюємо з організаціями та експертами, які створюють змістовні програми й відповідально ставляться до результатів навчання.","supporting_copy":"Партнерство може охоплювати розробку або представлення програми, експертну участь, освітню інфраструктуру, документи, реєстрацію та верифікацію. Ролі й відповідальність визначаються окремо для кожного проєкту.","primary_cta":"Запропонувати партнерство"},"body":"","cards":[]},{"key":"partnership_principles","title":"Partnership Principles","fields":{},"body":"- чіткі ролі та відповідальність сторін; - прозоре авторство й належне представлення експертів; - перевірений зміст і коректні публічні твердження; - визначені результати навчання й умови завершення; - окрема модель документів для кожної програми; - повага до авторських прав, даних слухачів і професійних меж.","cards":[]},{"key":"partnership_models","title":"Partnership Models","fields":{},"body":"","cards":[{"title":"Programme Partnership","fields":{},"body":"Для організацій, онлайн-шкіл і власників методик, які хочуть спільно структурувати, представити або реалізувати професійну програму."},{"title":"Expert Partnership","fields":{},"body":"Для практиків, викладачів і авторів, які долучаються до розробки змісту, викладання, оцінювання або професійної експертизи."},{"title":"Infrastructure Partnership","fields":{},"body":"Для освітніх проєктів, яким потрібна модель документів і додатків, реєстрація та онлайн-верифікація результатів навчання."}]},{"key":"academic_foundation","title":"Academic Foundation","fields":{"heading":"Ексклюзивне академічне партнерство","body":"Університет імені Альфреда Нобеля є ексклюзивним академічним партнером Nobel ITBS. Участь університету й тип університетського документа визначаються окремо для кожної програми та не поширюються автоматично на всі партнерські проєкти."},"body":"","cards":[]},{"key":"partner_organisations","title":"Partner Organisations","fields":{"heading":"Організації-партнери","intro":"Представляємо організації, роль яких у конкретних програмах або проєктах погоджена для публікації."},"body":"","cards":[{"title":"Рижський нордичний університет","fields":{"location":"м. Рига, Латвія","partner_role":"Організація-партнер","official_url":"https://rnu.lv/en/","asset_status":"З офіційного сайту отримано горизонтальний білий SVG та синій круглий знак PNG.","publication_status":"Поточну партнерську картку й отримані логотипи затверджено для Release 1."},"body":""},{"title":"Центр Психології Наталії Холоденко","fields":{"partner_role":"Організація-партнер","official_url":"https://school.kholodenko.net/","asset_status":"Офіційний квадратний знак у PNG отримано з лендінгу Центру.","publication_status":"Поточну партнерську картку й отриманий знак затверджено для Release 1."},"body":""},{"title":"Онлайн-школа e-launch","fields":{"partner_role":"Організація-партнер","official_url":"https://e-launch.net/","asset_status":"Отримано квадратний PNG із горизонтальним логотипом `e-launch`.","publication_status":"Поточну партнерську картку й отриманий логотип затверджено для Release 1."},"body":""}]},{"key":"experts","title":"Experts","fields":{"heading":"Експерти та автори програм","intro":"Знайомтеся з фахівцями, які створюють зміст, викладають або надають професійну експертизу в межах конкретних програм."},"body":"","cards":[{"title":"Наталія Холоденко","fields":{"public_category":"Психологиня, кандидат наук","expert_role":"Експертка та авторка освітніх програм","asset_status":"Отримано портретне фото у JPEG.","publication_status":"Поточний короткий профіль і фото затверджено для Release 1."},"body":""},{"title":"Дмитро Шевчук","fields":{"public_category":"Експерт-практик з маркетингу та продюсування освітніх проєктів","asset_status":"Отримано портретне фото у PNG.","publication_status":"Поточний короткий профіль, фото й експертну роль у програмі AI Production затверджено для Release 1."},"body":""}]},{"key":"partnership_boundaries","title":"Partnership Boundaries","fields":{},"body":"- partner and expert pages are not created in Release 1; - a logo is not proof of accreditation or universal endorsement; - partner participation is stated only for the relevant programme or project; - partners never appear in public credential verification data; - cooperation does not automatically create an academic partnership or right to issue university documents.","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"heading":"Маєте програму, експертизу або партнерську ідею?","copy":"Розкажіть про свою роль, проєкт і очікувану модель співпраці. Ми розглянемо, як вона може відповідати напряму Nobel ITBS.","primary_cta":"Запропонувати партнерство","fallback_cta":"Написати нам"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'partnerships'),
      'cz', 'published', 'Partnerství Nobel ITBS | Vzdělávání a expertiza', 'Modely partnerství Nobel ITBS pro vzdělávací organizace, online školy, experty a autory profesních programů.',
      'Partnerství, která posilují profesní vzdělávání', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Partnerships","h1":"Partnerství, která posilují profesní vzdělávání","lead":"Spolupracujeme s organizacemi a experty, kteří vytvářejí smysluplné programy a odpovědně přistupují k výsledkům vzdělávání.","supporting_copy":"Partnerství může zahrnovat vývoj nebo prezentaci programu, účast expertů, vzdělávací infrastrukturu, dokumenty, registraci a ověřování. Role a odpovědnost se určují samostatně pro každý projekt.","primary_cta":"Navrhnout partnerství"},"body":"","cards":[]},{"key":"partnership_principles","title":"Partnership Principles","fields":{},"body":"- jasné role a odpovědnost stran; - transparentní autorství a náležité představení expertů; - ověřený obsah a přesná veřejná tvrzení; - vymezené výsledky a podmínky dokončení; - samostatný model dokumentů pro každý program; - respekt k autorským právům, údajům účastníků a profesním hranicím.","cards":[]},{"key":"partnership_models","title":"Partnership Models","fields":{},"body":"","cards":[{"title":"Programme Partnership","fields":{},"body":"Pro organizace, online školy a vlastníky metodik, kteří chtějí společně strukturovat, představit nebo realizovat profesní program."},{"title":"Expert Partnership","fields":{},"body":"Pro praktiky, lektory a autory zapojené do tvorby obsahu, výuky, hodnocení nebo odborné expertizy."},{"title":"Infrastructure Partnership","fields":{},"body":"Pro vzdělávací projekty potřebující model dokumentů a dodatků, registraci a online ověřování výsledků."}]},{"key":"academic_foundation","title":"Academic Foundation","fields":{"heading":"Exkluzivní akademické partnerství","body":"Alfred Nobel University je exkluzivním akademickým partnerem Nobel ITBS. Účast univerzity a typ univerzitního dokumentu se určují zvlášť pro každý program a automaticky se nevztahují na všechny partnerské projekty."},"body":"","cards":[]},{"key":"partner_organisations","title":"Partner Organisations","fields":{"heading":"Partnerské organizace","intro":"Představujeme organizace, jejichž role v konkrétních programech nebo projektech byla schválena ke zveřejnění."},"body":"","cards":[]},{"key":"experts","title":"Experts","fields":{"heading":"Experti a autoři programů","intro":"Seznamte se s odborníky, kteří vytvářejí obsah, vyučují nebo poskytují profesní expertizu v konkrétních programech."},"body":"","cards":[{"title":"Nataliia Kholodenko","fields":{"public_category":"Psycholožka, kandidátka věd","expert_role":"Expertka a autorka vzdělávacích programů","asset_status":"Byla dodána portrétní fotografie ve formátu JPEG.","publication_status":"Aktuální stručný profil a fotografie jsou schváleny pro Release 1."},"body":""},{"title":"Dmytro Shevchuk","fields":{"public_category":"Praktický odborník na marketing a produkci vzdělávacích projektů","asset_status":"Byla dodána portrétní fotografie ve formátu PNG.","publication_status":"Aktuální stručný profil, fotografie a expertní role v programu AI Production jsou schváleny pro Release 1."},"body":""}]},{"key":"partnership_boundaries","title":"Partnership Boundaries","fields":{},"body":"- samostatné stránky partnerů a expertů nejsou součástí Release 1; - logo není důkazem akreditace ani univerzální podpory; - účast partnera se uvádí pouze u relevantního programu nebo projektu; - partneři se nikdy nezobrazují ve veřejných údajích ověřování dokumentu; - spolupráce automaticky nevytváří akademické partnerství ani právo vydávat univerzitní dokumenty.","cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"heading":"Máte program, expertizu nebo partnerský nápad?","copy":"Popište svou roli, projekt a očekávaný model spolupráce. Posoudíme, jak může odpovídat směru Nobel ITBS.","primary_cta":"Navrhnout partnerství","fallback_cta":"Napsat nám"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'for_organisations'),
      'en', 'published', 'Education Infrastructure for Online Schools | Nobel ITBS', 'Nobel ITBS infrastructure services for online schools and experts: programme structuring, documents and supplements, registration and verification.',
      'Education infrastructure for online schools and experts', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"B2B Infrastructure","h1":"Education infrastructure for online schools and experts","lead":"You create the content and learning experience. We help build the programme structure and a document system people can trust.","supporting_copy":"Nobel ITBS works as a provider and infrastructure partner for original and partner educational programmes. We help formalise the programme, define the document and supplement model, and organise registration and online verification.","primary_cta":"Discuss your project"},"body":"","cards":[]},{"key":"the_business_need","title":"The Business Need","fields":{},"body":"Strong content is not enough if a programme lacks clearly defined goals, scope, learning outcomes, completion requirements and a transparent document model. A learner, employer or partner needs to understand what was learned, to what extent, and how the issued document can be verified. Nobel ITBS helps bring these elements together into a coherent infrastructure without interfering with the partner''s methodology or original expertise.","cards":[]},{"key":"who_we_work_with","title":"Who We Work With","fields":{},"body":"","cards":[{"title":"Online Schools","fields":{},"body":"Schools that already teach learners and want to structure their programmes, standardise documents, and add registration and online verification."},{"title":"Experts And Programme Authors","fields":{},"body":"Experts who have a methodology, original course or professional programme and need a clear educational and document model."}]},{"key":"infrastructure_services","title":"Infrastructure Services","fields":{},"body":"","cards":[{"title":"Programme Structuring","fields":{},"body":"We help describe the programme''s purpose, audience, modules, learning scope, outcomes, assessment and completion requirements."},{"title":"Document Model","fields":{},"body":"We develop an aligned document model for the specific programme: the document title, the information it confirms, the supplement structure and its connection to learning outcomes."},{"title":"Document Preparation And Supplements","fields":{},"body":"We prepare the structure of certificates, diplomas or other agreed documents and supplements in accordance with the approved programme model."},{"title":"Registration And Verification","fields":{},"body":"We organise document registration and verification of a valid document by number or QR code, without public access to the private PDF."}]},{"key":"what_the_client_receives","title":"What The Client Receives","fields":{},"body":"- a structured educational programme description; - a defined outcomes and assessment model; - an agreed document and supplement system; - rules for preparing data used to issue documents; - registration of issued documents; - online validity verification by document number or QR code; - a clear allocation of roles and responsibilities between the parties. The exact service scope depends on the programme''s readiness, document type and chosen cooperation model.","cards":[]},{"key":"how_cooperation_works","title":"How Cooperation Works","fields":{"step_1_title":"We get to know the project","step_1_body":"We review the programme, audience, format, current learning model and intended outcome.","step_2_title":"We design the infrastructure","step_2_body":"We determine what needs to be structured, which documents are appropriate and how their preparation, registration and verification will work.","step_3_title":"We agree the model","step_3_body":"We document the scope of work, party roles, data requirements and rules for using the documents.","step_4_title":"We support implementation","step_4_body":"We work with the agreed programme and document infrastructure in accordance with the selected cooperation format."},"body":"","cards":[]},{"key":"trust_and_boundaries","title":"Trust And Boundaries","fields":{},"body":"Nobel ITBS operates through the Czech company Nobel ITBS s.r.o. and has an exclusive academic partnership with the University of Alfred Nobel. University participation, document type and the possibility of issuing that document are determined separately for each programme. Contacting Nobel ITBS does not guarantee programme approval, a university document, ECTS or any particular status.","cards":[]},{"key":"faq","title":"FAQ","fields":{},"body":"","cards":[{"title":"Does my programme need to be fully developed?","fields":{},"body":"No. You can approach us with a finished programme, an original methodology or a structure that still needs further development."},{"title":"Do I have to transfer intellectual property rights to Nobel ITBS?","fields":{},"body":"The rights and material-use model is agreed separately. Infrastructure cooperation does not itself mean an automatic transfer of intellectual property rights."},{"title":"Can every programme receive a university certificate?","fields":{},"body":"No. The document format and issuer depend on the content, scope, outcomes, assessment and agreed model of the specific programme."}]},{"key":"final_cta","title":"Final CTA","fields":{"heading":"Let us build the infrastructure for your educational programme","copy":"Tell us about the project, current learning format and documents you plan to issue. After an initial review, we will recommend the next step.","primary_cta":"Discuss your project","fallback_cta":"Contact us"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'for_organisations'),
      'ua', 'published', 'Освітня інфраструктура для онлайн-шкіл | Nobel ITBS', 'Інфраструктурні послуги Nobel ITBS для онлайн-шкіл та експертів: структурування програм, документи й додатки, реєстрація та верифікація.',
      'Освітня інфраструктура для онлайн-шкіл та експертів', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"B2B Infrastructure","h1":"Освітня інфраструктура для онлайн-шкіл та експертів","lead":"Ви створюєте зміст і навчальний досвід. Ми допомагаємо вибудувати структуру програми та систему документів, яким можна довіряти.","supporting_copy":"Nobel ITBS працює як провайдер та інфраструктурний партнер для авторських і партнерських освітніх програм. Ми допомагаємо оформити програму, визначити модель документів і додатків, організувати реєстрацію та онлайн-верифікацію.","primary_cta":"Обговорити проєкт"},"body":"","cards":[]},{"key":"the_business_need","title":"The Business Need","fields":{},"body":"Сильного контенту недостатньо, якщо програма не має чітко визначених цілей, обсягу, результатів навчання, правил завершення та зрозумілої моделі документів. Для слухача, роботодавця чи партнера важливо бачити, що саме було опановано, у якому обсязі та як можна перевірити виданий документ. Nobel ITBS допомагає зібрати ці елементи в цілісну інфраструктуру без втручання у методику або авторську експертизу партнера.","cards":[]},{"key":"who_we_work_with","title":"Who We Work With","fields":{},"body":"","cards":[{"title":"Online Schools","fields":{},"body":"Для шкіл, які вже навчають слухачів і хочуть структурувати програми, уніфікувати документи та додати реєстрацію й онлайн-верифікацію."},{"title":"Experts And Programme Authors","fields":{},"body":"Для експертів, які мають методику, авторський курс або професійну програму й потребують зрозумілої освітньої та документальної моделі."}]},{"key":"infrastructure_services","title":"Infrastructure Services","fields":{},"body":"","cards":[{"title":"Programme Structuring","fields":{},"body":"Допомагаємо описати мету, аудиторію, модулі, навчальний обсяг, результати, оцінювання та умови завершення програми."},{"title":"Document Model","fields":{},"body":"Формуємо узгоджену модель документів для конкретної програми: назву документа, дані, які він підтверджує, структуру додатка та зв’язок із результатами навчання."},{"title":"Document Preparation And Supplements","fields":{},"body":"Готуємо структуру сертифікатів, дипломів або інших погоджених документів і додатків відповідно до затвердженої моделі програми."},{"title":"Registration And Verification","fields":{},"body":"Організовуємо реєстрацію документів і можливість перевірки дійсного документа за номером або QR-кодом без публічного доступу до приватного PDF."}]},{"key":"what_the_client_receives","title":"What The Client Receives","fields":{},"body":"- структурований опис освітньої програми; - визначену модель результатів та оцінювання; - погоджену систему документів і додатків; - правила підготовки даних для видачі документів; - реєстрацію виданих документів; - онлайн-перевірку дійсності за номером або QR-кодом; - зрозумілий розподіл ролей і відповідальності між сторонами. Конкретний склад послуг залежить від готовності програми, типу документа та обраної моделі співпраці.","cards":[]},{"key":"how_cooperation_works","title":"How Cooperation Works","fields":{"step_1_title":"Знайомимося з проєктом","step_1_body":"Вивчаємо програму, аудиторію, формат, поточну модель навчання та очікуваний результат.","step_2_title":"Проєктуємо інфраструктуру","step_2_body":"Визначаємо, що потрібно структурувати, які документи доречні та як буде організовано їх підготовку, реєстрацію й перевірку.","step_3_title":"Погоджуємо модель","step_3_body":"Фіксуємо обсяг робіт, ролі сторін, вимоги до даних і правила використання документів.","step_4_title":"Підтримуємо реалізацію","step_4_body":"Працюємо з погодженою програмою та документальною інфраструктурою відповідно до обраного формату співпраці."},"body":"","cards":[]},{"key":"trust_and_boundaries","title":"Trust And Boundaries","fields":{},"body":"Nobel ITBS працює через чеську компанію Nobel ITBS s.r.o. та має ексклюзивне академічне партнерство з Університетом імені Альфреда Нобеля. Участь університету, тип документа та можливість його видачі визначаються для кожної програми окремо. Звернення до Nobel ITBS не гарантує автоматичного схвалення програми, університетського документа, ECTS або певного статусу.","cards":[]},{"key":"faq","title":"FAQ","fields":{},"body":"","cards":[{"title":"Чи потрібно мати повністю готову програму?","fields":{},"body":"Ні. Можна звернутися як із готовою програмою, так і з авторською методикою або структурою, яку ще потрібно доопрацювати."},{"title":"Чи обов’язково передавати авторські права Nobel ITBS?","fields":{},"body":"Модель прав і використання матеріалів погоджується окремо. Інфраструктурна співпраця сама по собі не означає автоматичної передачі авторських прав."},{"title":"Чи кожна програма може отримати університетський сертифікат?","fields":{},"body":"Ні. Формат і емітент документа залежать від змісту, обсягу, результатів, оцінювання та погодженої моделі конкретної програми."}]},{"key":"final_cta","title":"Final CTA","fields":{"heading":"Побудуймо інфраструктуру для вашої освітньої програми","copy":"Розкажіть про проєкт, поточний формат навчання та документи, які ви плануєте видавати. Ми запропонуємо наступний крок після первинного аналізу.","primary_cta":"Обговорити проєкт","fallback_cta":"Написати нам"},"body":"","cards":[]}]}'::jsonb
    ),
(
      (select id from public.content_pages where page_key = 'for_organisations'),
      'cz', 'published', 'Vzdělávací infrastruktura pro online školy | Nobel ITBS', 'Infrastrukturní služby Nobel ITBS pro online školy a experty: strukturování programů, dokumenty a dodatky, registrace a ověřování.',
      'Vzdělávací infrastruktura pro online školy a experty', '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"B2B Infrastructure","h1":"Vzdělávací infrastruktura pro online školy a experty","lead":"Vy vytváříte obsah a vzdělávací zkušenost. My pomáháme vybudovat strukturu programu a důvěryhodný systém dokumentů.","supporting_copy":"Nobel ITBS působí jako poskytovatel a infrastrukturní partner autorských a partnerských programů. Pomáháme formalizovat program, určit model dokumentů a dodatků a zajistit registraci a online ověřování.","primary_cta":"Projednat projekt"},"body":"","cards":[]},{"key":"the_business_need","title":"The Business Need","fields":{},"body":"Silný obsah nestačí bez jasných cílů, rozsahu, výsledků, podmínek dokončení a srozumitelného modelu dokumentů. Účastník, zaměstnavatel i partner musí vědět, co bylo absolvováno, v jakém rozsahu a jak dokument ověřit. Nobel ITBS propojuje tyto prvky bez zásahu do metodiky nebo autorské expertizy partnera.","cards":[]},{"key":"who_we_work_with","title":"Who We Work With","fields":{},"body":"","cards":[{"title":"Online Schools","fields":{},"body":"Pro školy, které již vzdělávají a chtějí strukturovat programy, sjednotit dokumenty a přidat registraci a ověřování."},{"title":"Experts And Programme Authors","fields":{},"body":"Pro experty s metodikou, autorským kurzem nebo profesním programem, kteří potřebují jasný vzdělávací a dokumentový model."}]},{"key":"infrastructure_services","title":"Infrastructure Services","fields":{},"body":"","cards":[{"title":"Programme Structuring","fields":{},"body":"Popis cíle, publika, modulů, rozsahu, výsledků, hodnocení a podmínek dokončení."},{"title":"Document Model","fields":{},"body":"Název dokumentu, potvrzované údaje, struktura dodatku a vazba na výsledky."},{"title":"Document Preparation And Supplements","fields":{},"body":"Struktura certifikátů, diplomů a dalších dohodnutých dokumentů a dodatků."},{"title":"Registration And Verification","fields":{},"body":"Registrace a ověření platného dokumentu číslem nebo QR kódem bez veřejného PDF."}]},{"key":"what_the_client_receives","title":"What The Client Receives","fields":{},"body":"- strukturovaný popis programu; - model výsledků a hodnocení; - dohodnutý systém dokumentů a dodatků; - pravidla přípravy dat; - registraci vydaných dokumentů; - online ověření číslem nebo QR kódem; - jasné rozdělení rolí a odpovědnosti. Rozsah závisí na připravenosti programu, typu dokumentu a modelu spolupráce.","cards":[]},{"key":"how_cooperation_works","title":"How Cooperation Works","fields":{"step_1_title":"Poznáme váš projekt","step_1_body":"Posoudíme program, publikum, formát, současný model a očekávaný výsledek.","step_2_title":"Navrhneme infrastrukturu","step_2_body":"Určíme, co strukturovat, jaké dokumenty jsou vhodné a jak proběhne jejich příprava, registrace a ověření.","step_3_title":"Dohodneme model","step_3_body":"Stanovíme rozsah, role, požadavky na data a pravidla použití dokumentů.","step_4_title":"Podpoříme realizaci","step_4_body":"Pracujeme podle dohodnutého programu, infrastruktury a formátu spolupráce."},"body":"","cards":[]},{"key":"trust_and_boundaries","title":"Trust And Boundaries","fields":{},"body":"Nobel ITBS působí prostřednictvím české společnosti Nobel ITBS s.r.o. a má exkluzivní akademické partnerství s Univerzitou Alfreda Nobela. Účast univerzity, typ dokumentu a možnost vydání se určují zvlášť pro každý program. Kontakt nezaručuje schválení, univerzitní dokument, ECTS ani určitý status.","cards":[]},{"key":"faq","title":"FAQ","fields":{},"body":"","cards":[{"title":"Musí být program hotový?","fields":{},"body":"Ne. Lze přijít s hotovým programem, metodikou i strukturou k dopracování."},{"title":"Musím převést autorská práva?","fields":{},"body":"Model práv se sjednává samostatně; infrastrukturní spolupráce automatický převod neznamená."}]}]}'::jsonb
